<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
import type { MulticaAgent, MulticaRuntime } from '../services/multica.service';
import { supportsReasoningEffort, type ReasoningEffort } from '../services/byok.service';
const props = defineProps<{ service: 'multica' | 'deepseek'; selectedId: string; agents: MulticaAgent[]; runtimes: MulticaRuntime[]; models: string[]; disabled?: boolean; loading?: boolean; error?: string; fallbackName?: string; effort?: ReasoningEffort }>();
const emit = defineEmits<{ chooseAgent: [id:string]; chooseModel:[id:string]; openSettings:[]; retry:[]; chooseEffort:[effort:ReasoningEffort] }>();
const root = ref<HTMLElement|null>(null), trigger = ref<HTMLButtonElement|null>(null), menu = ref<HTMLElement|null>(null), open = ref(false), opensUp = ref(false), menuHeight = ref(300), folder = ref<'multica'|'deepseek'|'effort'|null>(null);
const name = computed(() => props.service === 'deepseek' ? props.selectedId || '选择模型' : props.agents.find(a => a.id === props.selectedId)?.name || props.fallbackName || '选择助手');
function outside(event: PointerEvent) { if (root.value && !root.value.contains(event.target as Node)) { open.value = false; folder.value = null; } }
function updateDirection() { const rect = root.value?.getBoundingClientRect(), bounds = root.value?.closest('main')?.getBoundingClientRect(); if (!rect) return; const below = (bounds?.bottom ?? window.innerHeight) - rect.bottom - 12, above = rect.top - (bounds?.top ?? 0) - 12; opensUp.value = below < 180 && above > below; menuHeight.value = Math.max(100, Math.min(300, opensUp.value ? above : below)); }
function toggle() { if (!open.value) updateDirection(); open.value = !open.value; if (!open.value) folder.value = null; }
function focusFirst() { void nextTick(() => menu.value?.querySelector<HTMLButtonElement>('[role=menuitem]')?.focus()); }
function openWithKeyboard(e: KeyboardEvent) { if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return; e.preventDefault(); updateDirection(); open.value = true; focusFirst(); }
function menuKey(e: KeyboardEvent) {
  if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); open.value = false; folder.value = null; trigger.value?.focus(); return; }
  if (!['ArrowDown','ArrowUp','Home','End'].includes(e.key)) return;
  e.preventDefault(); const items = Array.from(menu.value?.querySelectorAll<HTMLButtonElement>('[role=menuitem]:not(:disabled)') || []); if (!items.length) return;
  const i = items.indexOf(document.activeElement as HTMLButtonElement);
  const n = e.key === 'Home' ? 0 : e.key === 'End' ? items.length - 1 : e.key === 'ArrowDown' ? (i + 1) % items.length : (i <= 0 ? items.length - 1 : i - 1);
  items[n]?.focus();
}
function showFolder(value:'multica'|'deepseek'|'effort'|null) { folder.value = value; focusFirst(); }
function selectAgent(id:string) { emit('chooseAgent',id); open.value=false; folder.value=null; }
function selectModel(id:string) { emit('chooseModel',id); open.value=false; folder.value=null; }
function runtime(id?:string) { return props.runtimes.find(r=>r.id===id)?.name || '未绑定运行时'; }
onMounted(()=>document.addEventListener('pointerdown',outside)); onBeforeUnmount(()=>document.removeEventListener('pointerdown',outside));
</script>
<template>
  <div ref="root" class="picker" @keydown.esc.stop.prevent="open=false; folder=null">
    <button ref="trigger" type="button" class="trigger" @keydown="openWithKeyboard" :disabled="disabled" :aria-expanded="open" aria-label="选择服务和模型" aria-haspopup="menu" @click="toggle"><span>{{ name }}</span><span class="chevron">⌄</span></button>
    <div v-if="open" ref="menu" class="menu" :class="{up:opensUp}" :style="{ maxHeight: `${menuHeight}px` }" role="menu" aria-label="选择服务和模型" @keydown="menuKey">
      <button v-if="folder" type="button" class="back" role="menuitem" @click="showFolder(null)">‹ 返回服务列表</button>
      <template v-if="!folder"><p class="heading">选择服务</p><button type="button" class="entry" role="menuitem" @click="showFolder('multica')"><span class="icon multica">✦</span><span class="copy"><strong>Multica</strong><small>{{ loading ? '加载助手中…' : `${agents.length} 个在线助手` }}</small></span><span>›</span></button><button type="button" class="entry" role="menuitem" @click="showFolder('deepseek')"><span class="icon deepseek">D</span><span class="copy"><strong>DeepSeek</strong><small>{{ models.length ? `${models.length} 个模型` : '请配置并获取模型' }}</small></span><span>›</span></button><div class="divider"></div><button type="button" class="entry" role="menuitem" :disabled="service !== 'deepseek' || !supportsReasoningEffort(selectedId)" @click="showFolder('effort')"><span class="icon multica">◌</span><span class="copy"><strong>思考强度</strong><small>{{ service !== 'deepseek' ? '由 Multica 助手配置' : !supportsReasoningEffort(selectedId) ? '当前模型未确认支持' : ({none:'关闭',low:'低',high:'高',max:'最高'}[effort || 'high']) }}</small></span><span>›</span></button></template>
      <template v-else-if="folder==='multica'"><p class="heading">Multica · 在线助手</p><button v-for="agent in agents" :key="agent.id" type="button" class="entry" role="menuitem" @click="selectAgent(agent.id)"><span class="icon multica">✦</span><span class="copy"><strong>{{ agent.name }}</strong><small>{{ agent.model || '默认模型' }} · {{ runtime(agent.runtime_id) }}</small></span><span v-if="service==='multica' && agent.id===selectedId">✓</span></button><p v-if="loading" class="empty">正在加载助手…</p><div v-else-if="error" class="empty">{{ error }} <button type="button" @click="emit('retry')">重试</button></div><p v-else-if="!agents.length" class="empty">暂无在线助手，请检查 Multica 连接。</p></template>
      <template v-else-if="folder==='effort'"><p class="heading">DeepSeek · 思考强度</p><button v-for="option in [{id:'none',label:'关闭'},{id:'low',label:'低'},{id:'high',label:'高'},{id:'max',label:'最高'}]" :key="option.id" type="button" class="entry" role="menuitem" @click="emit('chooseEffort',option.id as ReasoningEffort); open=false; folder=null"><span class="copy"><strong>{{ option.label }}</strong></span><span v-if="(effort || 'high')===option.id">✓</span></button><p class="empty">更高强度可能增加响应时间与费用。</p></template>
      <template v-else><p class="heading">DeepSeek · 可用模型</p><button v-for="model in models" :key="model" type="button" class="entry" role="menuitem" @click="selectModel(model)"><span class="icon deepseek">D</span><span class="copy"><strong>{{ model }}</strong><small>DeepSeek API</small></span><span v-if="service==='deepseek' && model===selectedId">✓</span></button><div v-if="!models.length" class="empty">请在设置中配置 Key 并获取模型。 <button type="button" @click="open=false; emit('openSettings')">打开设置</button></div></template>
    </div>
  </div>
</template>
<style scoped>
.picker{position:relative;flex:none;min-width:0}.trigger{display:flex;align-items:center;gap:7px;max-width:180px;border:0;border-radius:8px;padding:8px;background:transparent;color:var(--text,#35445d);font:inherit;font-size:12px;cursor:pointer}.trigger span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.trigger:hover,.trigger[aria-expanded=true]{background:var(--surface,#f2f4f8)}.trigger:focus-visible{outline:2px solid #64b5ef}.trigger:disabled{opacity:.5;cursor:not-allowed}.chevron{color:#8290a6;font-size:15px}.menu{position:absolute;right:0;top:calc(100% + 10px);z-index:30;width:280px;max-width:min(280px,75vw);max-height:300px;overflow:auto;padding:6px;border:1px solid var(--border,#dce3ec);border-radius:12px;background:var(--panel,#fff);box-shadow:0 8px 24px #17243b26}.menu.up{top:auto;bottom:calc(100% + 10px)}.divider{height:1px;background:var(--border,#e4e9f1);margin:5px 6px}.entry:disabled{opacity:.5;cursor:not-allowed}.heading{margin:8px 9px;color:var(--muted,#94a3b8);font-size:11px}.entry{width:100%;display:flex;align-items:center;gap:9px;padding:8px;border:0;border-radius:8px;background:transparent;color:var(--text,#29364b);font:inherit;text-align:left;cursor:pointer}.entry:hover,.entry:focus-visible{background:var(--surface,#eef1f5)}.icon{display:grid;place-items:center;flex:none;width:28px;height:28px;border-radius:8px;font-weight:700}.multica{background:#8170f41c;color:#806fe4}.deepseek{background:#477bf01c;color:#477bf0}.copy{min-width:0;flex:1}.copy strong,.copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.copy strong{font-size:12px}.copy small{margin-top:2px;font-size:10px;color:var(--muted,#97a4b8)}.back{width:100%;padding:8px;border:0;border-bottom:1px solid var(--border,#e4e9f1);background:transparent;color:#7569df;text-align:left;cursor:pointer}.empty{margin:10px;font-size:11px;color:var(--muted,#94a3b8);line-height:1.6}.empty button{border:0;background:transparent;color:#7569df;cursor:pointer}@media(max-width:850px){.trigger{max-width:110px}}
</style>
